∀ (l w0 : List Char) (m0 : ℕ),
    Id.run
        (have w := w0;
        have m := m0;
        do
        let r ←
          ForIn.forIn l ⟨m, w⟩ fun c r =>
              have m := r.fst;
              have w := r.snd;
              have w := Agent.LengthOfLongestSubstring.stepW w c;
              have m := Max.max m (List.length w);
              do
              Pure.pure PUnit.unit
              Pure.pure (ForInStep.yield ⟨m, w⟩)
        match r with
          | ⟨m, w⟩ => Pure.pure m) =
      (List.foldl Agent.LengthOfLongestSubstring.stepS (w0, m0) l).2

∀ {doc : String} {begin : ℕ} {strict : Bool}
    {motive :
      (a : Agent.JsonDecoder24.StringState) →
        (a_1 : Agent.JsonDecoder24.Outcome (String × ℕ)) →
          Agent.JsonDecoder24.StringExec doc begin strict a a_1 → Prop}
    {st : Agent.JsonDecoder24.StringState} {r : Agent.JsonDecoder24.Outcome (String × ℕ)}
    (a : Agent.JsonDecoder24.stringStep doc begin strict st = Agent.JsonDecoder24.StringStep.done r),
    Agent.JsonDecoder24.StringExec.below ⋯

∀ {α : Type} [Inhabited α] [DecidableEq α] (q : Gold.QueueThreadSafe.QueueCore α) (x : α),
    have q_sd := Gold.QueueThreadSafe.shutdown q;
    Gold.QueueThreadSafe.fifoPut q_sd x = Except.error Gold.QueueThreadSafe.QueueError.shutdown

∀ {α : Type} [inst : LinearOrder α] {q : Agent.QueueThreadsafe.Queue α} {x : α} {b : Bool}
    {t : Option Float} {q' : Agent.QueueThreadsafe.Queue α},
    Agent.QueueThreadsafe.Queue.put q x b t = Except.ok q' → q.isShutdown = Bool.false

∀ (redirectUrl : String) (allowedUrls : List String) (acc : Bool),
    (ForIn.forIn allowedUrls acc fun u found =>
        if (u == redirectUrl) = Bool.true then Pure.pure (ForInStep.yield Bool.true)
        else Pure.pure (ForInStep.yield found)) =
      (acc || List.contains allowedUrls redirectUrl)

∀ (stages : List Agent.UnsafeBootChain.Stage) (b : Bool),
    Id.run
        (have booted := b;
        do
        let r ←
          ForIn.forIn stages booted fun stage r =>
              have booted := r;
              have _fw := stage.1;
              have _sig := stage.2;
              have booted := booted;
              do
              Pure.pure PUnit.unit
              Pure.pure (ForInStep.yield booted)
        have booted : Bool := r
        Pure.pure booted) =
      b

